## Why This Is Asked

This question evaluates a candidate's ability to design interpretability and guardrail validation systems for production prompt services. It tests understanding of prompt component isolation, output attribution, safety constraint verification, and latency-aware auditing in a multi-tenant environment.

## Key Concepts

- Prompt fragmentation and attribution
- Guardrail activation detection
- Latency-aware auditing
- Multi-tenant considerations

## Code Example

```python
from dataclasses import dataclass
from typing import Dict, List, Optional
import time

@dataclass
class PromptFragment:
    fragment_type: str  # 'base_task', 'persona', or 'privacy_constraint'
    content: str

@dataclass
class AttributionResult:
    fragment: PromptFragment
    influence_score: float

@dataclass
class GuardVerdict:
    triggered: bool
    guard_type: Optional[str] = None
    details: Optional[str] = None

@dataclass
class PromptResult:
    attribution: AttributionResult
    guard_verdict: GuardVerdict
    latency_ms: float

class PromptAttributionGuard:
    def __init__(self, model, safety_classifier, metrics_backend):
        self.model = model
        self.safety_classifier = safety_classifier
        self.metrics = metrics_backend

    def decompose_prompt(self, composite_prompt: str) -> List[PromptFragment]:
        # Simplified decomposition - in production, use proper parsing
        fragments = []
        if 'task:' in composite_prompt:
            fragments.append(PromptFragment('base_task', self._extract_section(composite_prompt, 'task:')))
        if 'persona:' in composite_prompt:
            fragments.append(PromptFragment('persona', self._extract_section(composite_prompt, 'persona:')))
        if 'privacy:' in composite_prompt:
            fragments.append(PromptFragment('privacy_constraint', self._extract_section(composite_prompt, 'privacy:')))
        return fragments

    def _extract_section(self, prompt: str, prefix: str) -> str:
        lines = prompt.split('\n')
        for i, line in enumerate(lines):
            if line.strip().startswith(prefix):
                return ' '.join(lines[i:])
        return ''

    def compute_attribution(self, fragments: List[PromptFragment], full_output: str) -> AttributionResult:
        best_fragment = None
        best_score = -1
        for fragment in fragments:
            score = self._token_overlap_score(fragment.content, full_output)
            if score > best_score:
                best_score = score
                best_fragment = fragment
        return AttributionResult(fragment=best_fragment, influence_score=best_score)

    def _token_overlap_score(self, fragment: str, output: str) -> float:
        fragment_tokens = set(fragment.lower().split())
        output_tokens = set(output.lower().split())
        if not fragment_tokens:
            return 0.0
        return len(fragment_tokens & output_tokens) / len(fragment_tokens)

    def check_guardrails(self, output: str) -> GuardVerdict:
        prediction = self.safety_classifier.predict(output)
        if prediction['violation_detected']:
            return GuardVerdict(
                triggered=True,
                guard_type=prediction['guard_type'],
                details=prediction.get('details')
            )
        return GuardVerdict(triggered=False)

    def process(self, composite_prompt: str, tenant_id: str) -> PromptResult:
        start_time = time.perf_counter()

        fragments = self.decompose_prompt(composite_prompt)
        full_output = self.model.generate(composite_prompt)

        attribution = self.compute_attribution(fragments, full_output)
        guard_verdict = self.check_guardrails(full_output)

        latency_ms = (time.perf_counter() - start_time) * 1000

        self.metrics.log({
            'tenant_id': tenant_id,
            'latency_ms': latency_ms,
            'guard_triggered': guard_verdict.triggered,
            'guard_type': guard_verdict.guard_type,
            'influential_fragment': attribution.fragment.fragment_type
        })

        return PromptResult(
            attribution=attribution,
            guard_verdict=guard_verdict,
            latency_ms=latency_ms
        )

# Sample usage
if __name__ == '__main__':
    prompt1 = '''task: Summarize the document
persona: You are a professional editor
privacy: Do not mention any names'''

    prompt2 = '''task: Write a marketing email
persona: You are a casual friend
privacy: Do not include any PII'''

    harness = PromptAttributionGuard(
        model=MockModel(),
        safety_classifier=MockSafetyClassifier(),
        metrics_backend=MockMetricsBackend()
    )

    result1 = harness.process(prompt1, 'tenant_123')
    result2 = harness.process(prompt2, 'tenant_456')

    print(f'Prompt 1 - Influential fragment: {result1.attribution.fragment.fragment_type}')
    print(f'Prompt 1 - Guard triggered: {result1.guard_verdict.triggered}')
    print(f'Prompt 1 - Latency: {result1.latency_ms:.2f}ms')
    print(f'Prompt 2 - Influential fragment: {result2.attribution.fragment.fragment_type}')
    print(f'Prompt 2 - Guard triggered: {result2.guard_verdict.triggered}')
    print(f'Prompt 2 - Latency: {result2.latency_ms:.2f}ms')
```

This prototype demonstrates:
- **Fragment decomposition**: Splits composite prompts into base task, persona, and privacy constraint
- **Attribution**: Uses token overlap heuristic to identify the most influential fragment
- **Guard detection**: Evaluates outputs against a safety classifier
- **Latency logging**: Tracks per-prompt latency for performance monitoring
- **Multi-tenant support**: Includes tenant_id in metrics for isolated visibility

## Why This Is Asked
This question tests the ability to design a configurable policy framework that adapts prompts based on language and content risk, with traceable moderation reasoning and backpressure.

## Key Concepts
- Language detection and content classification
- Policy routing matrix (per-language, per-category)
- Guardrails and re-prompt loops
- Audit logging for moderation workflows

## Code Example
```javascript
// Minimal prototype: routePrompt(prompt, lang, category) -> {policy, rePrompt}
function routePrompt(prompt, lang, category){
  const policyKey = (category in policyMap && lang in policyMap[category]) ? policyMap[category][lang] : 'default';
  let rePrompt = null;
  const risk = scoreRisk(prompt, category, lang);
  if(risk > threshold){
    rePrompt = `Please comply with ${policyKey} before proceeding.`;
  }
  return {policy: policyKey, rePrompt};
}
```

